from typing import List, Literal, Optional
from pydantic import BaseModel, Field


class MarketReport(BaseModel):
    """Structured evaluation generated by MarketAnalyst."""
    core_pain_point: str = Field(description="Summary of the validated problem")
    urgency_score: int = Field(ge=1, le=10, description="1=nice-to-have, 10=hair-on-fire")
    target_buyer: str = Field(description="Specific economic buyer profile")
    adoption_blockers: List[str] = Field(description="Key friction points hindering customer adoption")


class CompetitionReport(BaseModel):
    """Structured evaluation generated by CompetitionAnalyst."""
    direct_competitors: List[str] = Field(description="Existing incumbents or emerging alternatives")
    switching_cost_rating: Literal["low", "medium", "high"] = Field(
        description="Friction for users to abandon current tools"
    )
    moat_defensibility: str = Field(description="Evaluation of defensive moat")
    kill_shot_risk: str = Field(
        description="Can a cloud or platform provider ship this feature natively and erase the product?"
    )


class RiskReport(BaseModel):
    """Structured evaluation generated by RiskAnalyst."""
    critical_risks: List[str] = Field(description="Fatal blockers (legal, security, compliance, liability)")
    data_privacy_concerns: List[str] = Field(description="PII, model data leakage, regulatory exposure")
    operational_fragility: str = Field(description="Dependency on third-party APIs, latency, or rate limits")
    overall_risk_level: Literal["low", "medium", "high", "critical"] = Field(
        description="Aggregate operational risk posture"
    )


class HumanReviewRecord(BaseModel):
    """Audit trail record produced when Human-in-the-Loop review is invoked."""
    reviewed_by: str = Field(description="Name or role of the reviewer")
    action_taken: Literal["approved", "overridden_to_pilot", "overridden_to_no_go"]
    reviewer_notes: str = Field(description="Mandatory rationale provided by the human reviewer")
    additional_stipulations: List[str] = Field(
        default_factory=list, description="Extra mandates or guardrails added by human"
    )


class LaunchMemo(BaseModel):
    """Consolidated executive memo synthesized from all analyst reports."""
    decision: Literal["go", "pilot", "no_go"] = Field(description="Final operational recommendation")
    confidence_score: float = Field(ge=0.0, le=1.0, description="Confidence score between 0.0 and 1.0")
    executive_summary: str = Field(description="High-level reasoning synthesizing all three reports")
    mandatory_mitigations: List[str] = Field(description="Required safeguards if proceeding")
    dissenting_concerns: List[str] = Field(description="Unresolved tensions among agent analyses")
    human_review: Optional[HumanReviewRecord] = Field(
        default=None, description="Audit record populated only if flagged for human intervention"
    )